// Tests the distribution generated by Java's Math.random() function.
public  class  TestRandom {

	
	public static void main(String[]  args) {
    int n = Integer.parseInt(args[0]);
	
	double x;
	double above = 0;
	double below = 0;

	for (int i = 0; i < n; i++){
	x = Math.random();
	if (x > 0.5){
		above ++;
	}
	else{
		below ++;
	}
  }

 	System.out.println("> 0.5: "+(int)above+" times");
	System.out.println("<= 0.5: "+(int)below+" times");
	if (below != 0) {
		double ratio = (double)(above/below);	
		System.out.println("Ratio: "+(double)ratio);
	}
 }
}
